import { ConflictError, ValidationError } from './errors';
import { TaskStatus } from './task-status';

function requiredText(value: string, field: string): string {
  const text = value.trim();
  if (!text) throw new ValidationError(`${field} is required`);
  return text;
}

export class User {
  public constructor(public readonly id: string, public readonly name: string) {
    requiredText(id, 'User id');
    requiredText(name, 'User name');
  }
}

export class Project {
  public constructor(public readonly id: string, public readonly name: string) {
    requiredText(id, 'Project id');
    requiredText(name, 'Project name');
  }
}

export class Task {
  public constructor(
    public readonly id: string,
    public readonly projectId: string,
    public readonly title: string,
    public readonly description: string | undefined,
    public readonly dueDate: Date | undefined,
    public readonly assigneeId: string | undefined,
    private currentStatus: TaskStatus = 'todo',
  ) {
    requiredText(id, 'Task id');
    requiredText(projectId, 'Project id');
    requiredText(title, 'Task title');
    if (description !== undefined) requiredText(description, 'Task description');
    if (dueDate !== undefined && Number.isNaN(dueDate.getTime())) {
      throw new ValidationError('Due date is invalid');
    }
  }

  public get status(): TaskStatus {
    return this.currentStatus;
  }

  public markDone(): void {
    if (this.currentStatus === 'done') {
      throw new ConflictError('Task is already done');
    }
    this.currentStatus = 'done';
  }
}

